export const normalizeTmSpeciesKey = (value) => String(value || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/\u2640/g, 'f')
  .replace(/\u2642/g, 'm')
  .replace(/[^a-z0-9]/g, '');

export const getPokemonTmCompatibility = (pokemon = {}, pokedex = {}) => {
  const base = pokedex[pokemon.id] || {};
  const candidates = [
    pokemon.formKey,
    pokemon.speciesKey,
    pokemon.name,
    base.formKey,
    base.speciesKey,
    base.name,
  ];
  const compactForm = String(pokemon.formKey || base.formKey || '')
    .toLowerCase()
    .replace(/-/g, '');
  if (compactForm) candidates.unshift(compactForm);
  const directName = String(pokemon.name || base.name || '');
  if (directName.endsWith('-H')) candidates.unshift(directName.replace(/-H$/, ' Hisui'));
  if (directName.endsWith('-A')) candidates.unshift(directName.replace(/-A$/, ' Alola'));
  if (directName.endsWith('-G')) candidates.unshift(directName.replace(/-G$/, ' Galar'));
  if (directName.endsWith('-P')) candidates.unshift(directName.replace(/-P$/, ' Paldea'));

  for (const candidate of candidates) {
    const key = normalizeTmSpeciesKey(candidate);
    if (TM_COMPATIBILITY_BY_SPECIES_KEY[key]) return TM_COMPATIBILITY_BY_SPECIES_KEY[key];
  }
  return [];
};
